-- Prax embedded-SQLite schema — consolidation of the seven Postgres
-- migrations (0001–0007) from the PostgreSQL era. Greenfield: the desktop app
-- creates a fresh local database; existing web installs migrate via the JSON
-- task export and .md library export/import.
--
-- Dialect notes (docs/desktop/checklist.md):
--   * uuid v4 ids are generated by a column DEFAULT expression (below);
--   * timestamps are ISO-8601 UTC text with milliseconds — the same string
--     shape pg's timestamptz produced over JSON, so API output is unchanged;
--   * booleans are INTEGER 0/1, normalized at the repository boundary;
--   * tags are a JSON text array handled with the JSON1 functions;
--   * full-text search is an external-content FTS5 table kept in sync by
--     triggers (replaces the tsvector GIN index);
--   * embedding columns are retained for the Phase-5 sqlite-vec follow-up but
--     are unused while EMBEDDING_BACKEND=none.

create table if not exists projects (
  id text primary key default (lower(hex(randomblob(4)) || '-' || hex(randomblob(2)) || '-4' || substr(hex(randomblob(2)),2) || '-' || substr('89ab', abs(random()) % 4 + 1, 1) || substr(hex(randomblob(2)),2) || '-' || hex(randomblob(6)))),
  name text not null,
  slug text not null unique,
  status text not null default 'active'
    check (status in ('active', 'on-hold', 'completed', 'archived')),
  sort_order integer not null default 0,
  created_at text not null default (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at text not null default (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

insert or ignore into projects (name, slug, sort_order) values
  ('Personal', 'personal', 0),
  ('Work', 'work', 1),
  ('Homelab', 'homelab', 2);

create table if not exists tasks (
  id text primary key default (lower(hex(randomblob(4)) || '-' || hex(randomblob(2)) || '-4' || substr(hex(randomblob(2)),2) || '-' || substr('89ab', abs(random()) % 4 + 1, 1) || substr(hex(randomblob(2)),2) || '-' || hex(randomblob(6)))),
  title text not null,
  description text not null default '',
  notes text not null default '',
  priority text not null check (priority in ('high', 'medium', 'low')),
  status text not null check (status in ('high-priority', 'in-progress', 'planned', 'completed', 'notes')),
  project_id text not null references projects(id),
  due_date text,
  sort_order integer not null default 0,
  archived_at text,
  created_at text not null default (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at text not null default (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

create index if not exists idx_tasks_project_status on tasks (project_id, status);
create index if not exists idx_tasks_archived_at on tasks (archived_at);
create index if not exists idx_tasks_due_date on tasks (due_date);

create table if not exists task_checklist_items (
  id text primary key default (lower(hex(randomblob(4)) || '-' || hex(randomblob(2)) || '-4' || substr(hex(randomblob(2)),2) || '-' || substr('89ab', abs(random()) % 4 + 1, 1) || substr(hex(randomblob(2)),2) || '-' || hex(randomblob(6)))),
  task_id text not null references tasks(id) on delete cascade,
  label text not null,
  completed integer not null default 0,
  sort_order integer not null default 0,
  created_at text not null default (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at text not null default (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

create index if not exists idx_task_checklist_items_task on task_checklist_items (task_id, sort_order);

create table if not exists task_activity (
  id text primary key default (lower(hex(randomblob(4)) || '-' || hex(randomblob(2)) || '-4' || substr(hex(randomblob(2)),2) || '-' || substr('89ab', abs(random()) % 4 + 1, 1) || substr(hex(randomblob(2)),2) || '-' || hex(randomblob(6)))),
  task_id text not null references tasks(id) on delete cascade,
  event_type text not null,
  message text not null,
  created_at text not null default (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

create index if not exists idx_task_activity_task on task_activity (task_id, created_at desc);

create table if not exists markdown_documents (
  id text primary key default (lower(hex(randomblob(4)) || '-' || hex(randomblob(2)) || '-4' || substr(hex(randomblob(2)),2) || '-' || substr('89ab', abs(random()) % 4 + 1, 1) || substr(hex(randomblob(2)),2) || '-' || hex(randomblob(6)))),
  title text not null,
  body text not null default '',
  document_type text not null check (document_type in ('runbook', 'note')),
  project_id text not null references projects(id),
  tags text not null default '[]',
  source_filename text,
  archived_at text,
  content_hash text,
  updated_by text not null default 'user',
  kind text not null default 'source' check (kind in ('source', 'synthesized')),
  verified integer not null default 0,
  verified_at text,
  verified_by text,
  status text not null default 'active' check (status in ('active', 'superseded', 'deprecated')),
  embedding text,
  embedding_backend text,
  embedding_model text,
  embedding_dim integer,
  embedded_hash text,
  embedded_at text,
  created_at text not null default (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at text not null default (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

create index if not exists idx_markdown_documents_project_type on markdown_documents (project_id, document_type);
create index if not exists idx_markdown_documents_archived_at on markdown_documents (archived_at);

create table if not exists task_documents (
  task_id text not null references tasks(id) on delete cascade,
  document_id text not null references markdown_documents(id) on delete cascade,
  created_at text not null default (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  primary key (task_id, document_id)
);

create index if not exists idx_task_documents_document on task_documents (document_id);

create table if not exists document_links (
  source_document_id text not null references markdown_documents(id) on delete cascade,
  target_document_id text not null references markdown_documents(id) on delete cascade,
  relation text not null,
  target_hash text,
  created_at text not null default (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  primary key (source_document_id, target_document_id, relation),
  check (source_document_id <> target_document_id)
);

create index if not exists idx_document_links_target on document_links (target_document_id, relation);

create table if not exists app_settings (
  key text primary key,
  value text not null,
  updated_at text not null default (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

-- Full-text search: external-content FTS5 over title + body, kept in sync by
-- triggers. Queries join back through rowid.
create virtual table if not exists markdown_documents_fts using fts5(
  title,
  body,
  content='markdown_documents',
  content_rowid='rowid'
);

create trigger if not exists markdown_documents_fts_ai after insert on markdown_documents begin
  insert into markdown_documents_fts (rowid, title, body)
  values (new.rowid, new.title, new.body);
end;

create trigger if not exists markdown_documents_fts_ad after delete on markdown_documents begin
  insert into markdown_documents_fts (markdown_documents_fts, rowid, title, body)
  values ('delete', old.rowid, old.title, old.body);
end;

create trigger if not exists markdown_documents_fts_au after update of title, body on markdown_documents begin
  insert into markdown_documents_fts (markdown_documents_fts, rowid, title, body)
  values ('delete', old.rowid, old.title, old.body);
  insert into markdown_documents_fts (rowid, title, body)
  values (new.rowid, new.title, new.body);
end;
